export const questionBank = [
  {id:"med-01",unit:"general-medicine",topic:"Cardiology",level:"Core",q:"A 58-year-old presents with acute central chest pressure. What is the most time-critical initial investigation?",o:["12-lead ECG","Exercise stress test","Routine echocardiogram","Lipid profile"],a:0,e:"Obtain and interpret a 12-lead ECG promptly in suspected acute coronary syndrome, alongside immediate clinical assessment and serial troponins. Do not delay emergency care."},
  {id:"med-02",unit:"general-medicine",topic:"Cardiology",level:"Core",q:"Which finding is most characteristic of left ventricular failure?",o:["Ascites","Pulmonary basal crepitations","Isolated splenomegaly","Unilateral calf swelling"],a:1,e:"Raised pulmonary venous pressure causes pulmonary congestion, often producing basal crepitations, orthopnoea and paroxysmal nocturnal dyspnoea."},
  {id:"med-03",unit:"general-medicine",topic:"Renal",level:"Core",q:"Tall, narrow peaked T waves on an ECG should make you suspect which electrolyte disturbance?",o:["Hypokalaemia","Hyperkalaemia","Hypocalcaemia","Hyponatraemia"],a:1,e:"Hyperkalaemia can cause peaked T waves, PR prolongation, loss of P waves and QRS widening. It can rapidly become life-threatening; assess and treat urgently."},
  {id:"med-04",unit:"general-medicine",topic:"Respiratory",level:"Clinical",q:"A patient with COPD is acutely breathless. Which bedside measurement is essential for assessing oxygenation?",o:["Peak flow only","Pulse oximetry","Abdominal girth","Visual acuity"],a:1,e:"Pulse oximetry rapidly estimates oxygen saturation. Interpret it with the clinical picture and obtain blood gases when indicated, particularly if hypercapnic respiratory failure is suspected."},
  {id:"med-05",unit:"general-medicine",topic:"Endocrinology",level:"Clinical",q:"A conscious patient with diabetes is sweaty, tremulous and has a capillary glucose of 2.4 mmol/L. What is the immediate action?",o:["Give oral fast-acting glucose if safe to swallow","Give long-acting insulin","Withhold all carbohydrate","Arrange HbA1c first"],a:0,e:"Treat conscious patients who can swallow with fast-acting oral glucose, then recheck glucose after about 10–15 minutes and provide longer-acting carbohydrate when recovered. If unable to swallow, use an appropriate emergency protocol."},

  {id:"sur-01",unit:"surgery",topic:"Acute abdomen",level:"Core",q:"Pain beginning around the umbilicus and later localising to the right iliac fossa is classically associated with:",o:["Acute appendicitis","Acute cholecystitis","Pancreatitis","Splenic rupture"],a:0,e:"Appendiceal visceral pain may begin peri-umbilically and migrate to the right iliac fossa as parietal peritoneum becomes involved. Consider age, pregnancy and alternative diagnoses."},
  {id:"sur-02",unit:"surgery",topic:"Trauma",level:"Core",q:"In the initial assessment of a severely injured patient, which sequence is used?",o:["AMPLE then discharge","ABCDE approach","Head-to-toe examination before resuscitation","Pain score only"],a:1,e:"Use a structured ABCDE primary survey: airway with cervical spine protection, breathing, circulation and haemorrhage control, disability, and exposure/environment. Treat life threats as found."},
  {id:"sur-03",unit:"surgery",topic:"Breast",level:"Clinical",q:"A new hard, irregular breast lump in an adult requires which approach?",o:["Reassurance without assessment","Triple assessment","Antibiotics for every patient","Mammography only in all ages"],a:1,e:"Triple assessment combines clinical examination, appropriate imaging and tissue diagnosis. The exact imaging pathway depends on age, pregnancy status and local protocol."},
  {id:"sur-04",unit:"surgery",topic:"Peri-operative",level:"Core",q:"Which is an important component of safe pre-operative assessment?",o:["Ignoring current medicines","Assessing comorbidities, airway, medicines and anaesthetic risk","Routine antibiotics for every operation","Avoiding consent discussion"],a:1,e:"Pre-operative assessment identifies physiological and anaesthetic risks, optimises comorbidities, reviews medicines/allergies, confirms informed consent and plans postoperative care."},

  {id:"paed-01",unit:"paediatrics",topic:"Emergency paediatrics",level:"Core",q:"A child is lethargic, unable to drink and has markedly sunken eyes. What should this raise concern for?",o:["No dehydration","Severe dehydration","Isolated constipation","Normal toddler behaviour"],a:1,e:"Inability to drink and lethargy are danger signs. Assess and manage urgently using the appropriate age-specific dehydration and shock protocol."},
  {id:"paed-02",unit:"paediatrics",topic:"Neonatology",level:"Core",q:"A newborn is not breathing adequately after birth. What is the priority intervention after initial steps?",o:["Wait for spontaneous recovery","Effective positive-pressure ventilation","Immediate oral feeding","Routine chest radiograph"],a:1,e:"Effective ventilation is the key intervention for a newborn who remains apnoeic or gasping after initial steps. Follow the current neonatal resuscitation algorithm and call for help."},
  {id:"paed-03",unit:"paediatrics",topic:"Growth",level:"Clinical",q:"Which tool is most useful for monitoring a child's growth trajectory over time?",o:["A single weight measurement","Serial measurements plotted on an appropriate growth chart","Adult BMI categories alone","Head circumference in every age group only"],a:1,e:"Plot serial weight, length/height and, where age-appropriate, head circumference on suitable growth charts. Interpret trajectory and clinical context, not one measurement alone."},
  {id:"paed-04",unit:"paediatrics",topic:"Immunisation",level:"Core",q:"When reviewing a child's immunisation history, the most reliable first step is to:",o:["Assume all vaccines were received","Review the vaccination card or reliable record and compare with the national schedule","Restart every vaccine automatically","Ask only the child's sibling"],a:1,e:"Verify doses and dates from a reliable record, then compare with the current national immunisation schedule and plan catch-up where indicated."},

  {id:"og-01",unit:"obstetrics-gynaecology",topic:"Hypertensive disorders",level:"Core",q:"A pregnant woman at 34 weeks has BP 170/115 mmHg, severe headache and visual symptoms. This is most concerning for:",o:["Physiological pregnancy","Pre-eclampsia with severe features","Simple nausea of pregnancy","White-coat hypertension without risk"],a:1,e:"Severe-range hypertension with neurological symptoms after 20 weeks is an obstetric emergency. Stabilise, assess mother and fetus, and follow urgent local pre-eclampsia protocols."},
  {id:"og-02",unit:"obstetrics-gynaecology",topic:"Postpartum haemorrhage",level:"Core",q:"Which uterotonic is commonly recommended first-line for prevention of postpartum haemorrhage after birth?",o:["Oxytocin","Magnesium sulphate","Diazepam","Nifedipine"],a:0,e:"Oxytocin is commonly first-line for prevention where available and not contraindicated. Follow current national guidance and the facility's active management of third stage protocol."},
  {id:"og-03",unit:"obstetrics-gynaecology",topic:"Early pregnancy",level:"Clinical",q:"A woman of reproductive age presents with lower abdominal pain and vaginal bleeding. What must be considered early?",o:["Ectopic pregnancy","Irritable bowel syndrome only","Primary dysmenorrhoea only","Urinary tract infection only"],a:0,e:"Always consider pregnancy and ectopic pregnancy in reproductive-age patients with abdominal/pelvic pain or bleeding. Assess haemodynamic stability and obtain pregnancy testing urgently."},
  {id:"og-04",unit:"obstetrics-gynaecology",topic:"Labour",level:"Core",q:"Which finding is a key reason to escalate urgently during labour?",o:["Reassuring fetal heart rate","Persistent pathological fetal heart rate pattern","Normal cervical progress","Maternal comfort"],a:1,e:"A persistent pathological fetal heart rate pattern may indicate fetal compromise. Confirm the signal, assess the whole clinical picture and escalate according to the intrapartum monitoring guideline."},

  {id:"em-01",unit:"emergency",topic:"Resuscitation",level:"Core",q:"An unresponsive adult is not breathing normally. What should you do after recognising cardiac arrest and calling for help?",o:["Start chest compressions","Give oral fluids","Wait for a pulse oximeter","Place in a chair"],a:0,e:"Start high-quality CPR promptly, obtain an AED/defibrillator and follow current basic and advanced life support guidance."},
  {id:"em-02",unit:"emergency",topic:"Shock",level:"Clinical",q:"Cold clammy skin, confusion, tachycardia and hypotension most strongly suggest:",o:["Circulatory shock","Stable chronic disease","Isolated anxiety in all cases","Normal physiology"],a:0,e:"These are features of impaired perfusion. Use ABCDE, identify the shock type and cause, obtain help, monitor and initiate cause-directed resuscitation."},
  {id:"em-03",unit:"emergency",topic:"Anaphylaxis",level:"Core",q:"A patient develops airway swelling, wheeze and hypotension minutes after a drug. First-line treatment is:",o:["Intramuscular adrenaline","Oral antihistamine alone","Nebulised saline alone","Observation only"],a:0,e:"Give intramuscular adrenaline promptly in suspected anaphylaxis, call for emergency help and follow the current anaphylaxis algorithm. Do not delay adrenaline for antihistamines."},
  {id:"em-04",unit:"emergency",topic:"Poisoning",level:"Clinical",q:"A patient presents after an unknown overdose. What is the safest initial approach?",o:["Induce vomiting","ABCDE stabilisation, focused history, examination and poison-specific advice","Give activated charcoal to everyone","Discharge if initially asymptomatic"],a:1,e:"Stabilise first using ABCDE, establish agent/time/dose where possible, assess toxidromes and investigations, and seek poison-centre or specialist advice. Decontamination is selective, not universal."},

  {id:"psy-01",unit:"psychiatry",topic:"Mental state examination",level:"Core",q:"Which of the following is a component of the mental state examination?",o:["Appearance and behaviour","Only past surgical history","Abdominal palpation","Visual acuity alone"],a:0,e:"The MSE includes appearance/behaviour, speech, mood/affect, thought form/content, perception, cognition, insight and judgement."},
  {id:"psy-02",unit:"psychiatry",topic:"Risk assessment",level:"Clinical",q:"A patient reports current suicidal thoughts with a plan and access to means. What is the priority?",o:["Ignore it if the patient is calm","Immediate safety assessment, supervision and urgent senior mental-health review","Promise secrecy","Routine review in six months"],a:1,e:"Assess immediate risk, intent, plan, means and protective factors; maintain safety, do not leave a high-risk patient unsupported, and urgently involve senior mental-health/emergency services."},
  {id:"psy-03",unit:"psychiatry",topic:"Psychosis",level:"Core",q:"A fixed false belief held despite clear contradictory evidence is termed:",o:["Delusion","Illusion","Compulsion","Phobia"],a:0,e:"A delusion is a fixed false belief not ordinarily shared by the person's cultural or subcultural group and maintained despite evidence to the contrary."},
  {id:"psy-04",unit:"psychiatry",topic:"Mood disorders",level:"Clinical",q:"Which feature is required to consider a manic episode?",o:["Persistently elevated, expansive or irritable mood with increased energy/activity","One brief episode of sadness","Fear of a specific object only","Isolated insomnia after night shift"],a:0,e:"Mania involves a distinct period of abnormal mood and increased energy/activity with associated symptoms and significant impairment or other defining consequences. Assess duration, severity, substances and medical causes."},

  {id:"com-01",unit:"community-medicine",topic:"Epidemiology",level:"Core",q:"Incidence measures:",o:["New cases occurring in a population over a specified period","All existing cases at one point only","Deaths among diagnosed patients only","The proportion of tests that are positive"],a:0,e:"Incidence quantifies new cases in a population at risk over a defined period. Prevalence counts existing cases at a point or over a period."},
  {id:"com-02",unit:"community-medicine",topic:"Screening",level:"Core",q:"A screening test is primarily intended to:",o:["Identify apparently well people who may have disease or increased risk","Confirm every diagnosis definitively","Replace clinical assessment","Treat disease directly"],a:0,e:"Screening identifies people who may benefit from further diagnostic assessment. A positive screen is not itself a definitive diagnosis."},
  {id:"com-03",unit:"community-medicine",topic:"Study design",level:"Clinical",q:"Which study design is generally most suitable for estimating prevalence?",o:["Cross-sectional study","Case report","Case-control study only","Ecological time series only"],a:0,e:"A cross-sectional study measures exposure and outcome in a defined population at a particular time or short period and is commonly used to estimate prevalence."},
  {id:"com-04",unit:"community-medicine",topic:"Prevention",level:"Core",q:"Immunisation to prevent infection is an example of:",o:["Primary prevention","Secondary prevention","Tertiary prevention","Quaternary prevention"],a:0,e:"Primary prevention acts before disease occurs, for example immunisation, health promotion and risk-factor reduction."},

  {id:"ort-01",unit:"orthopaedics",topic:"Fractures",level:"Core",q:"After a limb fracture, which assessment must be documented and repeated?",o:["Distal neurovascular status","Hair colour","Visual acuity","Bowel sounds only"],a:0,e:"Document distal pulses/perfusion, capillary refill, skin temperature, motor function and sensation before and after interventions, including splinting."},
  {id:"ort-02",unit:"orthopaedics",topic:"Compartment syndrome",level:"Clinical",q:"Severe pain out of proportion to injury and pain on passive stretch should raise concern for:",o:["Acute compartment syndrome","Simple bruising only","Osteoarthritis","Tendonitis"],a:0,e:"Pain out of proportion and pain on passive stretch are important early warning signs. This is a limb-threatening surgical emergency; urgent senior orthopaedic review is required."},
  {id:"ort-03",unit:"orthopaedics",topic:"Joint examination",level:"Core",q:"A standard joint examination is commonly structured as:",o:["Look, feel, move, function","Listen, smell, taste","Inspect abdomen, chest, head","History only"],a:0,e:"Use look, feel, move and function, comparing sides and examining relevant joints above and below the affected area."},
  {id:"ort-04",unit:"orthopaedics",topic:"Spine",level:"Clinical",q:"Back pain with saddle anaesthesia and new urinary retention requires urgent assessment for:",o:["Cauda equina syndrome","Mechanical back strain only","Migraine","Carpal tunnel syndrome"],a:0,e:"Saddle sensory loss and bladder/bowel dysfunction are red flags for cauda equina syndrome. Arrange emergency assessment and imaging through the local pathway."},

  {id:"med-05b",unit:"general-medicine",topic:"Neurology",level:"Core",q:"A patient develops sudden facial droop and unilateral arm weakness. What is the most important time detail to establish?",o:["Last-known-well time","Last bowel movement","Usual bedtime","Time of last meal"],a:0,e:"Establish the exact last-known-well time immediately because it determines eligibility for time-dependent acute stroke pathways. Activate the local stroke protocol."},
  {id:"med-06",unit:"general-medicine",topic:"Gastroenterology",level:"Clinical",q:"A patient has severe epigastric pain radiating to the back with vomiting. Which blood test is particularly useful when pancreatitis is suspected?",o:["Serum lipase","Troponin only","TSH","D-dimer"],a:0,e:"Serum lipase is commonly used in suspected acute pancreatitis. Interpret alongside characteristic pain and imaging where needed; assess severity and complications."},
  {id:"med-07",unit:"general-medicine",topic:"Infectious disease",level:"Core",q:"Which action is most appropriate when sepsis is suspected in an acutely unwell patient?",o:["Recognise, escalate and assess using ABCDE and local sepsis pathway","Wait for culture results before escalating","Give antipyretic and discharge","Avoid monitoring vital signs"],a:0,e:"Sepsis is time-critical. Escalate early, assess organ dysfunction and perfusion, obtain appropriate cultures and investigations, and initiate timely treatment according to local protocol."},
  {id:"med-08",unit:"general-medicine",topic:"Haematology",level:"Clinical",q:"Which blood film finding is classically associated with iron deficiency anaemia?",o:["Microcytic hypochromic red cells","Macro-ovalocytes with hypersegmented neutrophils","Spherocytes only","Sickle-shaped cells in every case"],a:0,e:"Iron deficiency typically produces microcytic, hypochromic red cells with increased variation in size/shape. Confirm with iron studies and investigate the cause."},

  {id:"sur-05",unit:"surgery",topic:"Bowel obstruction",level:"Core",q:"Which combination is classically associated with intestinal obstruction?",o:["Colicky pain, vomiting, distension and absolute constipation","Painless jaundice only","Polyuria and polydipsia","Isolated headache"],a:0,e:"The classic features are colicky abdominal pain, vomiting, abdominal distension and constipation/obstipation. Previous surgery and hernias are important clues."},
  {id:"sur-06",unit:"surgery",topic:"Wound care",level:"Core",q:"Which wound finding is most concerning for surgical site infection?",o:["Increasing erythema, warmth, pain and purulent discharge","A clean, dry wound with improving pain","Mild bruising immediately after surgery","A closed wound without discharge"],a:0,e:"Increasing erythema, warmth, tenderness, purulent discharge or systemic features suggest infection. Assess depth/severity and escalate according to local surgical guidance."},
  {id:"sur-07",unit:"surgery",topic:"Hernia",level:"Clinical",q:"A painful irreducible groin swelling with vomiting and abdominal distension raises concern for:",o:["Strangulated or obstructed hernia","An uncomplicated reducible hernia","Lipoma without symptoms","Varicocele"],a:0,e:"Painful irreducibility with obstructive symptoms may indicate incarceration, obstruction or strangulation. This requires urgent surgical assessment."},
  {id:"sur-08",unit:"surgery",topic:"Thyroid",level:"Clinical",q:"A patient with a thyroid swelling develops stridor and difficulty breathing. What is the priority?",o:["Urgent airway assessment and senior escalation","Routine outpatient review in six months","Thyroid function test only","Reassure without examination"],a:0,e:"Stridor suggests airway compromise. Prioritise airway assessment, urgent senior/anaesthetic/ENT involvement and emergency management."},

  {id:"paed-05",unit:"paediatrics",topic:"Neonatal jaundice",level:"Core",q:"Jaundice appearing within the first 24 hours of life should be regarded as:",o:["Pathological until assessed","Always physiological","Normal after every delivery","A reason to stop feeding"],a:0,e:"Jaundice in the first 24 hours is a red flag and needs prompt assessment for pathological causes, including haemolysis and infection."},
  {id:"paed-06",unit:"paediatrics",topic:"Nutrition",level:"Core",q:"Bilateral pitting oedema in a severely malnourished child is a defining feature of:",o:["Oedematous severe acute malnutrition","Simple stunting only","Normal growth","Isolated vitamin C deficiency"],a:0,e:"Bilateral pitting oedema is a defining feature of oedematous severe acute malnutrition. Assess for complications and follow a therapeutic feeding protocol."},
  {id:"paed-07",unit:"paediatrics",topic:"Respiratory",level:"Clinical",q:"In a child, which sign is a marker of increased work of breathing?",o:["Lower chest wall indrawing","Normal feeding and activity","Comfortable speech and play","Normal respiratory effort"],a:0,e:"Lower chest wall indrawing, nasal flaring, grunting and head bobbing can indicate respiratory distress. Assess severity, oxygenation and danger signs."},
  {id:"paed-08",unit:"paediatrics",topic:"Development",level:"Core",q:"Developmental assessment should primarily consider:",o:["Age-appropriate milestones across gross motor, fine motor, language and social domains","Only the child's height","Only school grades","A single milestone without age context"],a:0,e:"Assess multiple developmental domains and compare with age-appropriate expectations. Ask about regression, which is particularly concerning and requires evaluation."},

  {id:"og-05",unit:"obstetrics-gynaecology",topic:"Antenatal care",level:"Core",q:"At the first antenatal booking visit, which history is particularly important to establish?",o:["Obstetric history, medical conditions, medicines, allergies and gestational dating","Only the preferred baby's name","Only dietary preference","Only fetal movement"],a:0,e:"Booking assessment establishes dating, obstetric and medical risk, medications/allergies, prior pregnancy outcomes, screening needs and a plan for ongoing antenatal care."},
  {id:"og-06",unit:"obstetrics-gynaecology",topic:"Labour",level:"Clinical",q:"A woman in labour has heavy vaginal bleeding and a tender, hypertonic uterus. Which diagnosis is a major concern?",o:["Placental abruption","Uncomplicated show","Physiological Braxton Hicks only","Cervical ectropion"],a:0,e:"Painful bleeding with uterine tenderness/hypertonicity raises concern for placental abruption. Maternal resuscitation and urgent obstetric assessment are priorities."},
  {id:"og-07",unit:"obstetrics-gynaecology",topic:"Gynaecology",level:"Core",q:"Postmenopausal bleeding should be:",o:["Investigated promptly to exclude endometrial or other genital tract pathology","Assumed to be normal menstruation","Treated empirically without assessment","Ignored if painless"],a:0,e:"Any postmenopausal bleeding warrants timely evaluation because endometrial cancer and other pathology must be excluded, even if bleeding is painless or scanty."},
  {id:"og-08",unit:"obstetrics-gynaecology",topic:"Ectopic pregnancy",level:"Clinical",q:"A woman with possible early pregnancy has unilateral pelvic pain, shoulder-tip pain and syncope. What is the priority concern?",o:["Ruptured ectopic pregnancy with internal bleeding","Uncomplicated dysmenorrhoea","Normal pregnancy discomfort","Vaginal candidiasis"],a:0,e:"Shoulder-tip pain and syncope with pelvic pain may indicate haemoperitoneum from ruptured ectopic pregnancy. Treat as an emergency and assess haemodynamic stability."},

  {id:"em-05",unit:"emergency",topic:"Airway",level:"Core",q:"A patient has gurgling respirations and cannot protect their airway. What is the immediate priority?",o:["Airway opening, suction and urgent airway support","Give oral medication","Wait for a chest X-ray","Ask the patient to drink water"],a:0,e:"Gurgling suggests airway contamination. Call for help, open and clear the airway with suction as appropriate, provide oxygen/ventilation and prepare advanced airway support."},
  {id:"em-06",unit:"emergency",topic:"Hypoglycaemia",level:"Core",q:"An unconscious patient has a capillary glucose of 1.8 mmol/L. What is the key principle?",o:["Treat severe hypoglycaemia immediately using a safe non-oral route","Give food by mouth","Wait for laboratory confirmation","Administer insulin"],a:0,e:"Severe hypoglycaemia is an emergency. Do not give oral intake to an unconscious patient; use an appropriate IV glucose or glucagon protocol and recheck glucose."},
  {id:"em-07",unit:"emergency",topic:"Burns",level:"Clinical",q:"In a patient with major burns, what should be prioritised during the initial assessment?",o:["ABCDE, including early assessment for inhalational injury","Apply topical cream before assessment","Estimate burn depth only","Delay airway review until blisters form"],a:0,e:"Use ABCDE and consider inhalational injury early, especially with facial burns, soot, hoarseness or enclosed-space exposure. Follow local burn referral and fluid protocols."},
  {id:"em-08",unit:"emergency",topic:"Sepsis",level:"Clinical",q:"Which bedside parameter is useful for monitoring peripheral perfusion in shock?",o:["Capillary refill time","Hair texture","Visual acuity","Waist circumference"],a:0,e:"Capillary refill time, skin temperature, pulse quality, mental state and urine output help assess perfusion. Interpret together rather than relying on one sign."},

  {id:"psy-05",unit:"psychiatry",topic:"Depression",level:"Core",q:"Which symptom is a core feature of a depressive episode?",o:["Persistent low mood or loss of interest/pleasure","Brief normal sadness only","Elevated mood with reduced need for sleep","Specific fear of spiders only"],a:0,e:"Core symptoms include depressed mood and anhedonia, alongside other cognitive, biological and functional symptoms. Assess duration, impairment, differential diagnoses and suicide risk."},
  {id:"psy-06",unit:"psychiatry",topic:"Substance use",level:"Clinical",q:"A patient with heavy alcohol use stops abruptly and develops tremor, sweating and agitation. What should be considered?",o:["Alcohol withdrawal","Simple seasonal allergy","Uncomplicated migraine","Parkinson disease as the only possibility"],a:0,e:"Alcohol withdrawal can progress to seizures and delirium tremens. Assess severity, timing, autonomic signs and comorbidity; manage with an appropriate supervised protocol."},
  {id:"psy-07",unit:"psychiatry",topic:"Delirium",level:"Core",q:"Which feature is most suggestive of delirium rather than a stable chronic cognitive disorder?",o:["Acute onset with fluctuating attention and awareness","Slow progression over many years only","Stable lifelong learning difficulty","Isolated low mood"],a:0,e:"Delirium is an acute, fluctuating disturbance in attention and awareness, usually due to an underlying medical cause. Identify and treat the cause urgently."},
  {id:"psy-08",unit:"psychiatry",topic:"Mental health assessment",level:"Clinical",q:"When taking a psychiatric history, the mental state examination should be complemented by:",o:["Risk assessment and relevant physical/medical assessment","Only a urine dipstick in every case","No collateral history ever","Avoiding medication review"],a:0,e:"A complete assessment includes risk to self/others, safeguarding, substance use, physical health, medication review and collateral information where appropriate and consented."},

  {id:"com-05",unit:"community-medicine",topic:"Biostatistics",level:"Core",q:"Sensitivity is the proportion of:",o:["People with the disease who test positive","People without disease who test negative","Positive tests that are true positives","All participants who are disease-free"],a:0,e:"Sensitivity = true positives / all people with disease. A highly sensitive test has fewer false negatives; a negative result can help rule out disease in the right context."},
  {id:"com-06",unit:"community-medicine",topic:"Biostatistics",level:"Core",q:"Specificity is the proportion of:",o:["People without the disease who test negative","People with disease who test positive","All positive tests that are true positives","New cases per year"],a:0,e:"Specificity = true negatives / all people without disease. A highly specific test has fewer false positives."},
  {id:"com-07",unit:"community-medicine",topic:"Public health",level:"Clinical",q:"Contact tracing is primarily used to:",o:["Identify and manage people exposed to an infectious case","Replace vaccination programmes","Confirm every diagnosis by imaging","Measure hospital bed occupancy"],a:0,e:"Contact tracing identifies exposed people for risk assessment, testing, prophylaxis, monitoring or isolation as appropriate to the disease and public-health guidance."},
  {id:"com-08",unit:"community-medicine",topic:"Prevention",level:"Core",q:"Cervical cancer screening in an asymptomatic eligible population is an example of:",o:["Secondary prevention","Primary prevention only","Tertiary rehabilitation","Palliative care"],a:0,e:"Screening aims to detect precancerous lesions or early disease before symptoms, which is secondary prevention. Primary prevention includes HPV vaccination."},

  {id:"ort-05",unit:"orthopaedics",topic:"Fracture management",level:"Core",q:"The initial management of a suspected closed long-bone fracture should include:",o:["Analgesia, neurovascular assessment, immobilisation and appropriate imaging","Forceful repeated manipulation","Immediate weight-bearing in all cases","Ignoring distal pulses"],a:0,e:"Provide analgesia, document neurovascular status, immobilise the limb, obtain appropriate imaging and reassess neurovascular function after interventions."},
  {id:"ort-06",unit:"orthopaedics",topic:"Open fractures",level:"Clinical",q:"A patient has an open tibial fracture. Which action is important early?",o:["Cover with sterile dressing, give IV antibiotics promptly and arrange urgent orthopaedic assessment","Probe the wound repeatedly","Delay antibiotics until surgery","Close the wound tightly in the emergency room"],a:0,e:"Open fractures require prompt antibiotics, sterile wound coverage, tetanus assessment, immobilisation and urgent orthopaedic management/debridement according to protocol."},
  {id:"ort-07",unit:"orthopaedics",topic:"Osteoarthritis",level:"Core",q:"Which clinical pattern is typical of osteoarthritis?",o:["Joint pain worse with use and brief morning stiffness","Prolonged morning stiffness with systemic inflammatory features in every case","Sudden paralysis","Fever and purulent joint aspirate"],a:0,e:"Osteoarthritis commonly causes activity-related pain, short-lived morning stiffness, reduced function and bony enlargement. A hot acutely swollen joint requires exclusion of infection/crystal disease."},
  {id:"ort-08",unit:"orthopaedics",topic:"Septic arthritis",level:"Clinical",q:"An acutely hot, swollen, very painful joint with fever should prompt urgent consideration of:",o:["Septic arthritis","Uncomplicated osteoarthritis","Chronic tendon strain","Simple muscle fatigue"],a:0,e:"Septic arthritis is a time-critical joint emergency. Urgent aspiration for microscopy/culture and specialist assessment are needed; do not delay treatment in a systemically unwell patient."},

];

export const caseGuides = [
 {id:"pain",title:"Pain",group:"General presentations",intro:"Use a structured pain history, then adapt the questions to the anatomical site and suspected pathology.",steps:[
  ["Opening and context","Introduce yourself, confirm identity using local policy, obtain consent, ensure privacy, establish the patient's own description and ask what they think is happening."],
  ["Site and radiation","Ask the patient to point with one finger to the site. Is it localised or diffuse? Does it radiate to the back, shoulder, groin, jaw or limb? Map the distribution."],
  ["Onset and chronology","When did it start? Was onset sudden or gradual? What was the patient doing? Is it continuous, intermittent, recurrent or progressive? Establish exact duration and sequence."],
  ["Character and severity","Ask the patient to describe it in their own words: sharp, dull, aching, burning, stabbing, colicky, crushing or tearing. Use a 0–10 pain scale and ask how it affects function and sleep."],
  ["Aggravating and relieving factors","Explore movement, exertion, meals, breathing, coughing, posture, urination, defaecation, menstruation, touch, medicines and rest. Ask what has helped and whether relief is complete."],
  ["Associated symptoms","Tailor to site: fever, vomiting, breathlessness, sweating, palpitations, syncope, bowel or urinary symptoms, bleeding, weakness, numbness, rash or weight loss."],
  ["Danger signs","Screen for haemodynamic compromise, severe sudden onset, peritonism, chest pain with breathlessness/syncope, neurological deficit, pregnancy-related pain/bleeding, major trauma and sepsis."],
  ["Relevant background","Ask about previous similar episodes, known disease, operations, trauma, medications including analgesics/anticoagulants, allergies, family history and relevant social/occupational factors."],
  ["Close and summarise","Summarise onset, site, character, radiation, associated features, severity and red flags. Ask what has been missed, then explain the examination and next steps."]
 ],exam:"Assess general appearance, vital signs and pain behaviour. Examine the relevant system, compare sides, look for peritonism or neurovascular compromise where appropriate, and document positive and important negative findings.",differentials:"Build a site- and age-specific differential. Consider life-threatening causes first, then common local causes, referred pain and extra-organ causes. Do not anchor on one diagnosis.",workup:"Select investigations from the history and examination: bedside tests first where indicated (vitals, glucose, urine/pregnancy test, ECG), then targeted laboratory tests and imaging. Explain why each test is needed.",pitfalls:"Do not ask only 'does it hurt?'; do not assume the patient's pain score measures pathology; do not omit pregnancy possibility, analgesia, red flags or reassessment."},
 {id:"fever",title:"Fever",group:"General presentations",intro:"Clarify whether fever is measured or subjective, establish its pattern and search systematically for a source and severity.",steps:[
  ["Onset and duration","When did fever begin? Was it sudden or gradual? Continuous or episodic? Any documented temperature, thermometer method or antipyretic use?"],
  ["Pattern and severity","Ask about chills, rigors, sweats, night sweats and response to medication. Do not rely on fever pattern alone to identify an organism."],
  ["Localising symptoms","Respiratory: cough, sputum, dyspnoea. Urinary: dysuria, frequency, loin pain. Gastrointestinal: diarrhoea, vomiting, abdominal pain. Skin: wounds, rash, bites. CNS: headache, neck stiffness, confusion."],
  ["Exposure and epidemiology","Travel, mosquito exposure, sick contacts, outbreaks, food/water, animal exposure, occupation, sexual exposure where relevant, vaccination and recent healthcare contact."],
  ["Risk factors","Age, pregnancy, immunosuppression, HIV risk/testing history where appropriate, malignancy, diabetes, renal/liver disease, indwelling devices and recent surgery."],
  ["Severity and red flags","Confusion, respiratory distress, hypotension, poor perfusion, reduced urine output, inability to drink, persistent vomiting, seizures, non-blanching rash or suspected meningism."]
 ],exam:"Record temperature, pulse, BP, respiratory rate, oxygen saturation, mental state, hydration and perfusion. Examine skin, ENT, chest, abdomen, urinary system, joints and CNS guided by symptoms.",differentials:"Infection is common but consider inflammatory disease, malignancy, drug fever and thromboembolism. Prioritise sepsis, malaria in endemic settings, pneumonia, UTI, meningitis and enteric infection according to context.",workup:"Investigations are guided by severity and source: glucose, malaria testing where indicated, FBC, cultures before antibiotics when feasible without delaying urgent treatment, urinalysis, pregnancy test, renal function and targeted imaging.",pitfalls:"Do not label every fever as malaria. Avoid delaying sepsis treatment for tests. Interpret tests in clinical context and reassess after intervention."},
 {id:"cough",title:"Cough",group:"Respiratory",intro:"Characterise the cough, assess respiratory compromise and identify infectious, airway, cardiac and malignant causes.",steps:[
  ["Duration","Acute, subacute or chronic? Establish exact onset, progression and previous episodes."],
  ["Character","Dry or productive? If sputum, ask amount, colour, odour, blood, and whether it is frothy. Ask about paroxysms, barking quality or whoop."],
  ["Triggers and timing","Night, early morning, exercise, cold air, meals, lying flat, workplace exposure, smoke, dust or allergens?"],
  ["Associated symptoms","Fever, breathlessness, wheeze, chest pain, haemoptysis, weight loss, night sweats, reflux, nasal symptoms, leg swelling or orthopnoea."],
  ["Exposure and background","TB contact, smoking/vaping, biomass fuel, occupation, travel, sick contacts, immunisation, asthma/COPD, cardiac disease and ACE-inhibitor use."]
 ],exam:"Assess work of breathing, respiratory rate and oxygen saturation. Inspect, palpate, percuss and auscultate the chest; assess upper airway, lymph nodes, hydration and signs of heart failure.",differentials:"Consider URTI, pneumonia, asthma, COPD, TB, bronchiectasis, heart failure, reflux, post-nasal drip, medication-related cough and malignancy. Haemoptysis or systemic symptoms need careful assessment.",workup:"Depending on context: chest radiograph, sputum studies including TB testing, spirometry when stable, pulse oximetry, ECG, blood tests and further imaging if indicated.",pitfalls:"Do not overlook TB risk, haemoptysis, hypoxia or medication causes. Avoid diagnosing asthma or COPD from cough alone."},
 {id:"abdominal-pain",title:"Abdominal pain",group:"Gastrointestinal",intro:"Localise the pain, establish visceral versus peritoneal features, and screen early for pregnancy, obstruction, bleeding and sepsis.",steps:[
  ["Site and migration","Ask the patient to point to the pain. Did it begin elsewhere and migrate? Map to nine regions or quadrants; ask about radiation to back, shoulder or groin."],
  ["Onset, character and course","Sudden or gradual? Colicky, cramping, burning, sharp or constant? Progressive, intermittent or recurrent? Severity and effect on movement."],
  ["Gastrointestinal symptoms","Anorexia, nausea, vomiting (including bilious or bloody), distension, constipation, diarrhoea, last stool/flatus, melaena, rectal bleeding, jaundice and change in stool."],
  ["Urinary and reproductive history","Dysuria, frequency, haematuria, loin pain. Menstrual history, LMP, pregnancy possibility, vaginal bleeding/discharge, contraception and obstetric history where relevant."],
  ["Triggers and background","Relation to meals, fatty food, alcohol, defaecation, movement and medication. Previous episodes, surgery, gallstones, ulcers, hernias, liver disease and NSAID use."],
  ["Red flags","Shock, rigid abdomen, guarding, rebound, sudden severe pain, persistent vomiting, GI bleeding, fever with toxicity, pregnancy with pain/bleeding, pulsatile mass or inability to pass stool/flatus."]
 ],exam:"Start with general state and vital signs. Inspect distension/scars/hernias, auscultate, percuss and palpate gently, assess peritonism and organomegaly. Examine groins, rectum or pelvis only when indicated, with consent and chaperone.",differentials:"Use anatomical location and age/sex/pregnancy status. Consider appendicitis, biliary disease, pancreatitis, bowel obstruction/perforation, peptic ulcer, gastroenteritis, renal colic, UTI, ectopic pregnancy and pelvic pathology.",workup:"Consider pregnancy test in anyone with pregnancy potential, urinalysis, glucose, FBC, electrolytes/renal function, liver tests, lipase, ECG for upper abdominal pain where relevant, ultrasound or CT according to clinical question.",pitfalls:"Do not omit pregnancy testing, prior abdominal surgery, last stool/flatus, hernia examination or analgesia. A normal early examination does not exclude evolving surgical disease."},
 {id:"headache",title:"Headache",group:"Neurology",intro:"Differentiate primary headache from secondary headache and identify red flags for urgent neuroimaging or referral.",steps:[
  ["Onset","Thunderclap or gradual? Time to peak intensity? First or worst headache? At onset, during exertion, sex, cough or Valsalva?"],
  ["Phenotype","Site, unilateral/bilateral, throbbing/pressure, severity, duration, frequency and progression. Ask about aura and prodrome."],
  ["Associated symptoms","Nausea, vomiting, photophobia, phonophobia, visual loss, diplopia, weakness, numbness, speech difficulty, fever, neck stiffness, seizure or altered consciousness."],
  ["Context","Head injury, pregnancy/postpartum state, cancer, immunosuppression, anticoagulants, hypertension, infection, new medicines, analgesic overuse and family history."],
  ["Impact and previous treatment","Effect on daily function, sleep and work; previous episodes, diagnosis, medication, dose, response and adverse effects."],
  ["Red flags","Sudden thunderclap, focal deficit, fever/meningism, papilloedema, new onset in older age, pregnancy/postpartum, cancer/immunosuppression, trauma, progressive pattern or altered consciousness."]
 ],exam:"Record vital signs and mental state. Perform full neurological examination including cranial nerves, power, sensation, coordination, gait and fundoscopy when competent; assess meningism and temporal arteries where relevant.",differentials:"Migraine, tension-type and cluster headache are common primary causes. Exclude subarachnoid haemorrhage, meningitis, intracranial mass, cerebral venous thrombosis, hypertensive emergency, glaucoma and medication-overuse headache.",workup:"Urgent imaging or lumbar puncture depends on red flags and local pathway. Consider glucose, pregnancy testing, inflammatory markers and other tests guided by suspected cause.",pitfalls:"Do not diagnose migraine before screening red flags. Avoid lumbar puncture where contraindications or raised intracranial pressure concerns exist; follow local protocols."},
 {id:"dyspnoea",title:"Shortness of breath",group:"Respiratory",intro:"Assess severity immediately, then characterise onset, triggers, associated symptoms and likely cardiopulmonary cause.",steps:[
  ["Immediate severity","Can the patient speak full sentences? Onset sudden or gradual? At rest or exertion? Rapid progression? Any cyanosis, exhaustion or confusion?"],
  ["Character and pattern","Orthopnoea, number of pillows, paroxysmal nocturnal dyspnoea, wheeze, episodic attacks, exercise tolerance and baseline function."],
  ["Associated symptoms","Chest pain, cough, sputum, fever, haemoptysis, palpitations, syncope, leg swelling/pain, weight loss or allergic symptoms."],
  ["Risk factors","Asthma/COPD, heart disease, anaemia, thromboembolism, recent surgery/immobility, pregnancy, smoking, infection exposure and medication history."]
 ],exam:"ABCDE first. Record RR, SpO2, pulse, BP, temperature and mental state. Inspect work of breathing; examine chest, JVP, heart, peripheral oedema and calves where appropriate.",differentials:"Consider asthma/COPD exacerbation, pneumonia, pulmonary oedema, pulmonary embolism, pneumothorax, ACS/arrhythmia, anaemia, metabolic acidosis and anxiety only after dangerous causes are assessed.",workup:"Pulse oximetry, ECG, chest radiograph, blood gas when indicated, FBC, renal function, troponin/BNP or D-dimer only according to pre-test probability, and targeted imaging.",pitfalls:"Do not let a normal oxygen saturation exclude serious disease. Do not delay emergency treatment for investigations in an unstable patient."},
 {id:"vomiting",title:"Nausea and vomiting",group:"Gastrointestinal",intro:"Determine the nature and duration of vomiting, assess dehydration and identify obstruction, intracranial, metabolic and pregnancy-related causes.",steps:[
  ["Timeline and frequency","When did it begin? Number of episodes, volume, progression, relation to meals or waking, and ability to retain fluids."],
  ["Contents","Food, bile, blood/coffee-ground material or faeculent material? Projectile? Any preceding nausea or retching?"],
  ["Associated features","Abdominal pain/distension, diarrhoea, constipation, fever, headache, vertigo, chest pain, urinary symptoms, polyuria/polydipsia or weight loss."],
  ["Pregnancy and exposures","LMP and pregnancy possibility, medicines, alcohol/recreational substances, toxins, travel, food exposures and sick contacts."],
  ["Complications and red flags","Reduced urine, dizziness/syncope, confusion, severe pain, bilious/faeculent vomiting, haematemesis, distension, neurological deficit or severe dehydration."]
 ],exam:"Assess hydration, perfusion, vitals, abdominal distension/tenderness/peritonism, neurological status and signs of metabolic disease.",differentials:"Gastroenteritis, pregnancy, bowel obstruction, appendicitis, pancreatitis, DKA, medication/toxin effects, intracranial pathology and vestibular disease.",workup:"Consider glucose/ketones, electrolytes/renal function, pregnancy test, urinalysis, FBC, lipase and imaging guided by suspected obstruction or abdominal pathology.",pitfalls:"Do not assume gastroenteritis in persistent vomiting. Replace fluids/electrolytes appropriately and reassess."},
 {id:"diarrhoea",title:"Diarrhoea",group:"Gastrointestinal",intro:"Define stool frequency and consistency, distinguish acute from chronic diarrhoea, and assess dehydration and dysentery.",steps:[
  ["Definition and duration","How many stools per day? Watery or formed? Acute, persistent or chronic? Baseline bowel habit and urgency/nocturnal symptoms?"],
  ["Stool characteristics","Blood, mucus, pus, greasy stool, pale stool, offensive smell or black stool? Tenesmus or incontinence?"],
  ["Associated symptoms","Fever, abdominal cramps, vomiting, weight loss, dehydration, rash, joint symptoms or oral ulcers."],
  ["Exposure","Unsafe water/food, travel, sick contacts, outbreak, antibiotics, hospital admission, animal contact and immunosuppression."],
  ["Red flags","Blood in stool, severe dehydration, shock, severe abdominal pain, high fever/toxicity, persistent symptoms, infant/older age or immunocompromise."]
 ],exam:"Assess hydration, perfusion, weight, vitals, abdominal tenderness/distension and nutritional status. Examine perianal region or rectum only if clinically indicated.",differentials:"Infective gastroenteritis, dysentery, medication-related diarrhoea, inflammatory bowel disease, malabsorption, IBS and endocrine causes.",workup:"Oral rehydration is central where appropriate. Stool testing is selective based on blood, severity, duration, outbreak or risk; consider FBC, electrolytes and further tests for chronic symptoms.",pitfalls:"Avoid routine antibiotics or antimotility drugs in every case, especially bloody diarrhoea or suspected invasive infection. Assess hydration repeatedly."},
 {id:"pv-bleeding",title:"Bleeding per vaginam",group:"Obstetrics & Gynaecology",intro:"First establish stability and pregnancy status. Then characterise bleeding by age, menstrual context and associated pelvic symptoms.",steps:[
  ["Stability and severity","Amount, pads used, clots, flooding, dizziness, syncope, palpitations, breathlessness and ongoing bleeding. Assess urgently if unstable."],
  ["Pregnancy possibility","LMP, cycle regularity, sexual activity where relevant, contraception, pregnancy test, prior ectopic pregnancy, miscarriage and fertility treatment."],
  ["Bleeding pattern","Onset, duration, frequency, intermenstrual, postcoital, postmenopausal, relation to menses and previous episodes."],
  ["Associated symptoms","Lower abdominal/pelvic pain, shoulder-tip pain, fever, discharge, dyspareunia, urinary/bowel symptoms and pregnancy symptoms."],
  ["Obstetric/gynaecological background","Gravidity/parity, gestational age if pregnant, previous complications, fibroids, polyps, cervical screening, procedures, medications including anticoagulants and family history."]
 ],exam:"ABCDE if heavy bleeding or unstable. Record vitals, pallor and perfusion; abdominal examination. Pelvic/speculum examination only when indicated, with informed consent, chaperone and appropriate expertise.",differentials:"Pregnancy-related: miscarriage, ectopic pregnancy, molar pregnancy, placenta praevia/abruption depending on gestation. Non-pregnant: fibroids, polyps, adenomyosis, ovulatory dysfunction, coagulopathy, infection and malignancy.",workup:"Pregnancy test is essential when pregnancy is possible. Consider FBC, blood group/crossmatch if significant, pelvic ultrasound and targeted cervical/infection/endometrial assessment.",pitfalls:"Never assume bleeding is menstruation. Exclude pregnancy/ectopic pregnancy. Postmenopausal bleeding requires prompt investigation."},
 {id:"seizure",title:"Seizure or loss of consciousness",group:"Neurology",intro:"Establish whether the event was epileptic, describe it from a witness and identify reversible causes and immediate threats.",steps:[
  ["Event description","What happened before, during and after? Obtain witness account: onset, eye/head deviation, stiffening, jerking, symmetry, duration, colour, breathing and injuries."],
  ["Awareness and recovery","Was awareness lost? Tongue bite (especially lateral), incontinence, post-event confusion, headache, muscle pain, focal weakness and time to baseline."],
  ["Triggers and context","Sleep deprivation, fever, alcohol/drug withdrawal, missed medication, flashing lights, head injury, pregnancy, metabolic illness or new medicines."],
  ["Previous history","Prior episodes, epilepsy diagnosis, seizure type, medication/adherence, febrile seizures, CNS infection, stroke, developmental history and family history."],
  ["Red flags","First seizure, prolonged/recurrent seizure without recovery, persistent altered consciousness, focal deficit, fever/meningism, trauma, pregnancy or hypoglycaemia."]
 ],exam:"Protect airway and assess ABCDE, glucose, vitals, injuries and neurological status. Look for meningism, focal signs, toxidrome and pregnancy-related complications.",differentials:"Epileptic seizure, syncope, psychogenic non-epileptic event, hypoglycaemia, arrhythmia, stroke, CNS infection and metabolic/toxic causes.",workup:"Immediate capillary glucose; ECG for possible syncope/arrhythmia; electrolytes, pregnancy test and toxicology when indicated; EEG and neuroimaging based on clinical assessment and local guidance.",pitfalls:"Do not put objects in the mouth or restrain the patient. Time the seizure, protect from injury and follow status epilepticus protocol for prolonged seizures."},
 {id:"vaginal-discharge",title:"Vaginal discharge",group:"Obstetrics & Gynaecology",intro:"Characterise discharge and assess for vaginitis, cervicitis, STI, pregnancy and pelvic inflammatory disease.",steps:[
  ["Description","Colour, amount, consistency, odour, duration, cyclical variation and whether it is different from the patient's normal discharge."],
  ["Associated symptoms","Itching, soreness, dysuria, dyspareunia, lower abdominal pain, fever, intermenstrual or postcoital bleeding."],
  ["Sexual and reproductive history","Ask sensitively about partners, condom use, STI exposure, previous STI, contraception, LMP and pregnancy possibility. Explain confidentiality and its limits."],
  ["Predisposing factors","Recent antibiotics, diabetes, pregnancy, vaginal products/douching, foreign body possibility and recurrent episodes."]
 ],exam:"General and abdominal assessment if systemic symptoms or pelvic pain. External genital/speculum examination and swabs when indicated, with consent and chaperone.",differentials:"Physiological discharge, bacterial vaginosis, candidiasis, trichomoniasis, cervicitis (including gonorrhoea/chlamydia), foreign body and pelvic inflammatory disease.",workup:"Use local STI testing pathways; microscopy/point-of-care testing or NAAT as appropriate, pregnancy testing and partner assessment/treatment when indicated.",pitfalls:"Do not diagnose solely by colour or odour. Consider STI and pregnancy; avoid stigma and ensure partner notification is handled confidentially."},
 {id:"weakness",title:"Weakness or limb weakness",group:"Neurology",intro:"Clarify subjective fatigue versus objective loss of power, localise the lesion and rapidly exclude stroke and spinal emergencies.",steps:[
  ["Clarify symptom","Is it tiredness, heaviness, pain-limited movement or true loss of power? Which limb(s), proximal/distal, one side or both?"],
  ["Onset and progression","Sudden or gradual? Exact last-known-well time for acute focal deficit. Progressive, fluctuating, ascending or episodic?"],
  ["Associated neurological symptoms","Face droop, speech/vision change, numbness, imbalance, swallowing difficulty, bladder/bowel symptoms, saddle sensory loss, back/neck pain or headache."],
  ["Systemic context","Fever, weight loss, breathlessness, palpitations, bleeding, diabetes, medications, toxins, recent infection and family history."]
 ],exam:"Assess ABCDE and glucose. Perform focused neurological examination: cranial nerves, tone, power by muscle group, reflexes, sensation, coordination and gait when safe. Examine spine if indicated.",differentials:"Stroke/TIA, spinal cord or cauda equina compression, peripheral neuropathy, neuromuscular junction disease, myopathy, electrolyte disturbance, anaemia and systemic illness.",workup:"Acute stroke pathway and urgent imaging when indicated; glucose, electrolytes, FBC, ECG and further tests guided by localisation and clinical picture.",pitfalls:"Do not delay stroke assessment to complete a lengthy history. Document onset/last-known-well and objective power grading."},
 {id:"jaundice",title:"Jaundice",group:"Gastrointestinal",intro:"Determine the onset and pattern, distinguish pre-hepatic, hepatocellular and cholestatic features, and identify liver failure or obstruction.",steps:[
  ["Onset and progression","When noticed? Sudden or gradual? Persistent or fluctuating? Previous episodes or known liver disease?"],
  ["Urine and stool","Dark urine, pale/clay stool, pruritus and steatorrhoea suggest conjugated hyperbilirubinaemia/cholestasis."],
  ["Associated symptoms","Fever/rigors, right upper quadrant pain, nausea, vomiting, weight loss, anorexia, fatigue, bruising, confusion or abdominal swelling."],
  ["Exposures and risks","Alcohol, prescribed/over-the-counter/herbal medicines, viral hepatitis risks, transfusion, injections, tattoos, travel, food/water, family history and metabolic disease."]
 ],exam:"Assess mental state/encephalopathy, vitals, nutrition, scratch marks, bruising, stigmata of chronic liver disease, hepatosplenomegaly, ascites and abdominal masses.",differentials:"Haemolysis, viral/drug-induced hepatitis, alcohol-related liver disease, autoimmune/metabolic disease, gallstones, biliary obstruction and pancreaticobiliary malignancy.",workup:"LFT pattern, FBC, coagulation/INR, renal function, viral hepatitis tests and ultrasound; further imaging/serology guided by findings. Urgent referral for encephalopathy or coagulopathy.",pitfalls:"Confusion with jaundice may indicate acute liver failure. Fever, jaundice and RUQ pain may indicate ascending cholangitis—an emergency."},
 {id:"urinary",title:"Urinary symptoms",group:"Renal & Urology",intro:"Separate storage, voiding and post-micturition symptoms; assess infection, obstruction, haematuria and renal impairment.",steps:[
  ["Symptom classification","Dysuria, frequency, urgency, nocturia, hesitancy, weak stream, intermittency, straining, terminal dribbling, incomplete emptying or incontinence."],
  ["Associated features","Fever, rigors, loin/suprapubic pain, haematuria, urethral discharge, genital lesions, retention, nausea/vomiting and reduced urine output."],
  ["Risk factors","Pregnancy, sexual history when relevant, stones, prostate disease, diabetes, neurological disease, catheterisation, recurrent UTI, renal disease and medicines."],
  ["Impact and chronology","Onset, duration, progression, fluid/caffeine intake, effect on sleep/daily life, previous tests/treatment and response."]
 ],exam:"Vitals and sepsis assessment; abdominal/suprapubic palpation, renal angle tenderness, external genital examination when indicated, prostate or neurological examination according to presentation and consent.",differentials:"UTI, pyelonephritis, urethritis/STI, stones, bladder outlet obstruction, prostatitis, malignancy, overactive bladder and neurogenic bladder.",workup:"Urinalysis and culture where indicated, pregnancy test, renal function, bladder scan/post-void residual and imaging for obstruction, stones or haematuria according to pathway.",pitfalls:"Do not treat asymptomatic bacteriuria routinely outside specific indications. Visible haematuria requires appropriate evaluation."},
 {id:"trauma",title:"Trauma and injury",group:"Emergency & Surgery",intro:"Use a structured trauma primary survey before a detailed mechanism-focused history and secondary survey.",steps:[
  ["Mechanism and time","What happened, when, speed/height/energy, fall or collision direction, weapon, protective equipment, restraint, ejection and number of impacts?"],
  ["Immediate events","Loss of consciousness, amnesia, seizure, vomiting, bleeding, ability to walk, extrication and pre-hospital treatment."],
  ["Symptoms by region","Headache, neck/back pain, chest pain, dyspnoea, abdominal pain, limb pain, numbness, weakness and deformity."],
  ["Background","AMPLE: allergies, medications (especially anticoagulants), past medical history/pregnancy, last meal and events/environment. Tetanus status and safeguarding concerns where relevant."],
  ["Red flags","Airway compromise, respiratory distress, shock/major haemorrhage, altered consciousness, focal deficit, penetrating torso injury, unstable pelvis and neurovascular compromise."]
 ],exam:"Primary survey ABCDE with simultaneous life-saving interventions, exposure and temperature control. Then head-to-toe secondary survey, log-roll when indicated, document wounds and repeat neurovascular checks.",differentials:"Identify life-threatening injuries first: intracranial, cervical spine, chest, abdominal/pelvic haemorrhage, long-bone fractures and compartment syndrome.",workup:"Use trauma imaging protocols based on stability and mechanism; bedside glucose, bloods, group/crossmatch, FAST or CT as indicated. Do not delay resuscitation for imaging in an unstable patient.",pitfalls:"Do not miss occult haemorrhage, hypothermia, anticoagulant use or repeated neurovascular assessment. Follow local trauma protocols."},
];
